"""Compare a candidate results file against one or more references (grader's three thresholds).

    python score.py reference.jsonl candidate.jsonl
    python score.py --ref tune=ref_tune.jsonl --ref holdout=ref_holdout.jsonl candidate.jsonl [--json out.json]

With --ref, each reference defines a set of parquet files (from its second lines and its error lines);
the candidate is filtered to those files and scored against that reference alone. An empty reference
is a FAIL. --only-common scores only the videos present in both files and labels the result PARTIAL.
Standard library only. Exit code 0 only if every set is a full PASS, 1 otherwise.
"""
import argparse
import json
import sys
from collections import defaultdict

F1_MIN = 0.95
EXACT_MIN = 0.85
WITHIN1_MIN = 0.95


def parse_lines(lines):
    """Iterable of dicts -> (seconds, errors).
    seconds: {(video, second): (frozenset(objects), people)}; errors: {video: message}."""
    seconds, errors = {}, {}
    for d in lines:
        video = d.get("video")
        if "error" in d:
            errors[video] = d["error"]
        elif "second" in d:
            seconds[(video, d["second"])] = (frozenset(d.get("objects", [])), d.get("people", 0))
    return seconds, errors


def load_results(path):
    bad = 0
    lines = []
    with open(path, encoding="utf-8") as f:
        for raw in f:
            raw = raw.strip()
            if not raw:
                continue
            try:
                lines.append(json.loads(raw))
            except ValueError:
                bad += 1
    if bad:
        print(f"warning: {bad} unparseable lines in {path}", file=sys.stderr)
    return parse_lines(lines)


def f1(tp, fp, fn):
    denom = 2 * tp + fp + fn
    return 1.0 if denom == 0 else 2 * tp / denom


def compute(ref, cand):
    """ref, cand: (seconds, errors) as returned by parse_lines. Returns a metrics dict."""
    ref_s, ref_e = ref
    cand_s, cand_e = cand
    per_video = defaultdict(lambda: [0, 0, 0])  # tp, fp, fn
    exact = within1 = total = 0
    people_by_video = defaultdict(lambda: [0, 0])  # exact hits, seconds

    for key, (r_obj, r_ppl) in ref_s.items():
        c_obj, c_ppl = cand_s.get(key, (frozenset(), 0))  # missing second == empty
        tp, fp, fn = len(r_obj & c_obj), len(c_obj - r_obj), len(r_obj - c_obj)
        v = per_video[key[0]]
        v[0] += tp
        v[1] += fp
        v[2] += fn
        total += 1
        people_by_video[key[0]][1] += 1
        if c_ppl == r_ppl:
            exact += 1
            people_by_video[key[0]][0] += 1
        if abs(c_ppl - r_ppl) <= 1:
            within1 += 1
    for key, (c_obj, _) in cand_s.items():
        if key not in ref_s:  # extra second: every claimed object is a false positive
            per_video[key[0]][1] += len(c_obj)

    tp = sum(v[0] for v in per_video.values())
    fp = sum(v[1] for v in per_video.values())
    fn = sum(v[2] for v in per_video.values())
    video_f1 = {vid: f1(*v) for vid, v in per_video.items()}
    return {
        "micro_f1": f1(tp, fp, fn),
        "macro_f1": sum(video_f1.values()) / len(video_f1) if video_f1 else 1.0,
        "people_exact": exact / total if total else 1.0,
        "people_within1": within1 / total if total else 1.0,
        "ref_seconds": total,
        "cand_seconds": len(cand_s),
        "missing_seconds": sum(1 for k in ref_s if k not in cand_s),
        "extra_seconds": sum(1 for k in cand_s if k not in ref_s),
        "ref_errors": len(ref_e),
        "cand_errors": len(cand_e),
        "error_mismatch": len(set(ref_e) ^ set(cand_e)),
        "video_f1": video_f1,
        "video_people_exact": {k: (h / n if n else 1.0) for k, (h, n) in people_by_video.items()},
    }


def passes(m):
    return {
        "objects micro F1": (m["micro_f1"], F1_MIN),
        "people exact": (m["people_exact"], EXACT_MIN),
        "people within +-1": (m["people_within1"], WITHIN1_MIN),
    }


def report(m, worst=10, out=None):
    out = out or sys.stdout
    ok = True
    for name, (value, threshold) in passes(m).items():
        good = value >= threshold
        ok &= good
        print(f"{'PASS' if good else 'FAIL'}  {name}: {value:.4f} (need >= {threshold})", file=out)
    print(f"macro F1 per video: {m['macro_f1']:.4f}", file=out)
    print(
        f"seconds: ref {m['ref_seconds']}, cand {m['cand_seconds']}, "
        f"missing {m['missing_seconds']}, extra {m['extra_seconds']}",
        file=out,
    )
    print(
        f"error lines: ref {m['ref_errors']}, cand {m['cand_errors']}, "
        f"mismatched videos {m['error_mismatch']}",
        file=out,
    )
    if m["video_f1"]:
        print(f"worst {worst} videos (F1, people exact):", file=out)
        ranked = sorted(m["video_f1"].items(), key=lambda kv: (kv[1], m["video_people_exact"].get(kv[0], 1.0)))
        for vid, score in ranked[:worst]:
            print(f"  {vid}: F1 {score:.3f}, people exact {m['video_people_exact'].get(vid, 1.0):.3f}", file=out)
    return ok


def file_of(video):
    """Parquet file name of a video id "<file>:<row>"."""
    return str(video).rpartition(":")[0]


def file_set(parsed):
    """Parquet files that appear in a parsed results file, in second lines or in error lines."""
    seconds, errors = parsed
    return {file_of(v) for v, _ in seconds} | {file_of(v) for v in errors}


def video_set(parsed):
    seconds, errors = parsed
    return {v for v, _ in seconds} | set(errors)


def restrict(parsed, keep):
    """Keep only entries whose video satisfies keep(video). Returns (filtered, number of videos dropped)."""
    seconds, errors = parsed
    dropped = {v for v in video_set(parsed) if not keep(v)}
    return (
        {k: v for k, v in seconds.items() if keep(k[0])},
        {v: m for v, m in errors.items() if keep(v)},
    ), len(dropped)


def score_set(name, ref, cand, only_common=False):
    """Score parsed candidate against parsed reference -> result dict (status PASS / FAIL / PARTIAL)."""
    files = file_set(ref)
    cand_f, ignored = restrict(cand, lambda v: file_of(v) in files)
    ref_f = ref
    if only_common:
        common = video_set(ref) & video_set(cand_f)
        ref_f, _ = restrict(ref, common.__contains__)
        cand_f, _ = restrict(cand_f, common.__contains__)
    m = compute(ref_f, cand_f)
    empty = m["ref_seconds"] == 0
    ok = (not empty) and all(v >= t for v, t in passes(m).values())
    if empty or not ok:
        status = "FAIL"
    else:
        status = "PARTIAL" if only_common else "PASS"
    return {"name": name, "metrics": m, "status": status, "empty_reference": empty,
            "files": sorted(files), "ignored_candidate_videos": ignored, "only_common": only_common}


def score_files(refs, cand_path, only_common=False, worst=10, out=None):
    """refs: [(name, path)]. Prints one block per set and a summary. Returns (results, all_pass)."""
    out = out or sys.stdout
    cand = load_results(cand_path)
    results = []
    for name, path in refs:
        r = score_set(name, load_results(path), cand, only_common)
        results.append(r)
        print(f"== {name}: {path} ({len(r['files'])} files) ==", file=out)
        if r["empty_reference"]:
            print("FAIL  reference has no seconds: nothing to score", file=out)
        else:
            report(r["metrics"], worst, out)
        print(f"candidate videos ignored (files not in this reference): {r['ignored_candidate_videos']}", file=out)
        if only_common:
            print("PARTIAL: only videos present in both files were scored", file=out)
    print("== summary ==", file=out)
    for r in results:
        m = r["metrics"]
        print(f"{r['status']}  {r['name']}: F1 {m['micro_f1']:.4f}, exact {m['people_exact']:.4f}, "
              f"within1 {m['people_within1']:.4f}, seconds {m['ref_seconds']}", file=out)
    all_pass = bool(results) and all(r["status"] == "PASS" for r in results)
    print(f"overall: {'PASS' if all_pass else 'NOT PASS'}", file=out)
    return results, all_pass


def result_json(r):
    m = r["metrics"]
    keys = ("micro_f1", "macro_f1", "people_exact", "people_within1", "ref_seconds", "cand_seconds",
            "missing_seconds", "extra_seconds", "ref_errors", "cand_errors", "error_mismatch")
    d = {k: m[k] for k in keys}
    d.update(status=r["status"], ignored_candidate_videos=r["ignored_candidate_videos"],
             files=r["files"], only_common=r["only_common"])
    return d


def parse_ref(text):
    name, sep, path = text.partition("=")
    if not sep or not name or not path:
        raise argparse.ArgumentTypeError(f"--ref must be NAME=PATH, got {text!r}")
    return name, path


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("files", nargs="*", help="REFERENCE CANDIDATE, or just CANDIDATE when --ref is used")
    ap.add_argument("--ref", action="append", type=parse_ref, default=[], metavar="NAME=PATH")
    ap.add_argument("--only-common", action="store_true", help="score only videos present in both files (PARTIAL)")
    ap.add_argument("--json", default=None, metavar="PATH", help="write metrics per set as JSON")
    ap.add_argument("--worst", type=int, default=10)
    args = ap.parse_args(argv)
    if args.ref:
        if len(args.files) != 1:
            ap.error("with --ref give exactly one positional argument: the candidate")
        refs, cand = args.ref, args.files[0]
    else:
        if len(args.files) != 2:
            ap.error("give REFERENCE CANDIDATE (or --ref NAME=PATH ... CANDIDATE)")
        refs, cand = [("reference", args.files[0])], args.files[1]
    results, ok = score_files(refs, cand, args.only_common, args.worst)
    if args.json:
        with open(args.json, "w", encoding="utf-8") as f:
            json.dump({"sets": {r["name"]: result_json(r) for r in results}, "overall_pass": ok}, f, indent=2)
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())
"""Model-free frame count: demux every video (no decoding) and count its video packets.

    python tools/count_frames.py --input /content/finevideo/data --out frame_counts.csv [--workers 8]
        [--compare-dumps DIR]

Counts packets on the stream chosen by vidx.decode.pick_video_stream, skipping packets with size 0 (flush)
or is_discard. CSV columns: file,row,video_id,frames,duration_s,width,height,codec,error.
--compare-dumps compares each count with len(t) of the video's dump npz (written by run.py --dump-frames).
PyAV is imported only when a video is really demuxed.
"""
import argparse
import csv
import io
import sys
from collections import defaultdict
from concurrent.futures import ProcessPoolExecutor
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

COLUMNS = ["file", "row", "video_id", "frames", "duration_s", "width", "height", "codec", "error"]


def count_packets(packets):
    """Pure counting. packets: iterable of objects with .size and .is_discard.
    Returns (frames, error); on an exception while iterating the count so far is kept."""
    n = 0
    try:
        for p in packets:
            if p.size == 0 or getattr(p, "is_discard", False):
                continue
            n += 1
    except Exception as e:
        return n, f"{type(e).__name__}: {e}"[:200]
    return n, None


def demux_video(data):
    """Real PyAV demux of one mp4 buffer -> dict(frames, duration_s, width, height, codec, error)."""
    import av

    from vidx.decode import pick_video_stream

    container = av.open(io.BytesIO(memoryview(data)))
    try:
        stream = pick_video_stream(container)
        if stream is None:
            raise ValueError("no video stream")
        frames, error = count_packets(container.demux(stream))
        duration = None
        if stream.duration is not None and stream.time_base:
            duration = float(stream.duration * stream.time_base)
        elif container.duration:
            duration = container.duration / 1_000_000
        ctx = stream.codec_context
        return {"frames": frames, "duration_s": duration, "width": ctx.width, "height": ctx.height,
                "codec": ctx.name, "error": error}
    finally:
        container.close()


def summarize_video(video_id, data, err, demux_fn=demux_video):
    """One CSV row (dict) for a video; any failure goes into the error column."""
    file, _, row = video_id.rpartition(":")
    out = {"file": file, "row": row, "video_id": video_id, "frames": None, "duration_s": None,
           "width": None, "height": None, "codec": None, "error": None}
    if err:
        out["error"] = err
        return out
    try:
        out.update(demux_fn(data))
    except Exception as e:
        out["error"] = f"{type(e).__name__}: {e}"[:200]
    return out


def process_file(path, demux_fn=demux_video, rows_fn=None):
    if rows_fn is None:
        from vidx.source import iter_rows as rows_fn
    return [summarize_video(vid, data, err, demux_fn) for vid, data, err in rows_fn(Path(path))]


def _worker(path):
    return process_file(path)


def write_csv(rows, out):
    Path(out).parent.mkdir(parents=True, exist_ok=True)
    with open(out, "w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=COLUMNS)
        w.writeheader()
        for r in rows:
            w.writerow({k: ("" if r.get(k) is None else r[k]) for k in COLUMNS})


def totals(rows):
    """videos, frames, hours and the share of frames per resolution."""
    frames = sum(r["frames"] or 0 for r in rows)
    hours = sum(r["duration_s"] or 0 for r in rows) / 3600
    by_res = defaultdict(int)
    for r in rows:
        if r["frames"] and r["width"] and r["height"]:
            by_res[f"{r['width']}x{r['height']}"] += r["frames"]
    share = {k: v / frames for k, v in sorted(by_res.items(), key=lambda kv: -kv[1])} if frames else {}
    return {"videos": len(rows), "errors": sum(1 for r in rows if r["error"]), "frames": frames,
            "hours": hours, "resolution_share": share}


def _npz_len(path):
    import numpy as np

    with np.load(path) as z:
        return len(z["t"])


def compare_dumps(rows, dump_dir, npz_len=_npz_len):
    """Compare packet counts with len(t) of each dump npz. Returns a summary dict."""
    from run import npz_paths

    compared = missing = 0
    sum_count = sum_dump = 0
    worst = (0, None)
    for r in rows:
        if not r["frames"]:
            continue
        path = npz_paths(dump_dir, r["video_id"])[1]
        if not path.exists():
            missing += 1
            continue
        n = npz_len(path)
        compared += 1
        sum_count += r["frames"]
        sum_dump += n
        gap = abs(r["frames"] - n)
        if gap > worst[0]:
            worst = (gap, r["video_id"])
    pct = 100.0 * (sum_count - sum_dump) / sum_dump if sum_dump else 0.0
    return {"compared": compared, "missing_dumps": missing, "largest_gap": worst[0],
            "largest_gap_video": worst[1], "total_gap_pct": pct, "sum_count": sum_count, "sum_dump": sum_dump}


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--input", required=True, help="folder of .parquet files (or one file)")
    ap.add_argument("--out", required=True, help="CSV to write")
    ap.add_argument("--workers", type=int, default=8)
    ap.add_argument("--compare-dumps", default=None, metavar="DIR")
    args = ap.parse_args(argv)
    src = Path(args.input)
    files = [src] if src.is_file() else sorted(src.glob("*.parquet"))
    if not files:
