        path = npz_paths(dump_dir, r["video_id"])[1]
        if not path.exists():
            missing += 1
            continue
        n = npz_len(path)
        compared += 1
        sum_count += r["frames"]
        sum_dump += n
        gap = abs(r["frames"] - n)
        if gap > worst[0]:
